// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette(); }

    function testFuzz_property(address caller, uint64 advanceSeconds) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));

        advanceSeconds = uint64(bound(advanceSeconds, 1, 1000));

        vm.deal(caller, 20 ether);

        vm.warp(block.timestamp + uint256(advanceSeconds));

        vm.prank(caller);
        (bool ok, ) = address(c).call{value: 10 ether}('');
        uint256 stored = c.pastBlockTime();

        assertTrue(ok && stored != block.timestamp);
    }
}
